"""Read durable search summaries and emit the train-only search evidence table."""
from pathlib import Path
import json,time
H=Path(__file__).resolve().parent

def read(p):return json.loads(p.read_text())
def main():
 reg=read(H/'preregister.json');configs=reg['configs']+(read(H/'supplemental-config.json')['configs'] if (H/'supplemental-config.json').exists() else []);rows=[]
 for job in reg['jobs']:
  for config in configs:
   folder=H/'runs'/job['map_id']/config['name'];p=folder/'summary.json'
   if not p.exists():continue
   r=read(p);m=r.get('metrics',{});c=m.get('constructor_metrics',{});g=read(folder/'greedy-progress.json') if (folder/'greedy-progress.json').exists() else {}
   rows.append(dict(map_id=job['map_id'],n_loads=job['n_loads'],variant=config['name'],status=r.get('status'),solver_complete=r.get('solver_complete'),checker_certified=r.get('checker_certified'),wall_s=r.get('elapsed_s'),budget_s=r.get('config',{}).get('budget_s') if isinstance(r.get('config'),dict) else None,carrier_fraction=r.get('config',{}).get('carrier_fraction',.5) if isinstance(r.get('config'),dict) else None,greedy_status=m.get('preplan_greedy_primary_status'),preplan_time_s=m.get('preplan_time_s'),greedy_budget_s=m.get('preplan_greedy_primary_budget_s'),greedy_time_s=m.get('preplan_greedy_primary_time_s'),constructor_requested_s=m.get('constructor_requested_time_s'),greedy_max_aboard=g.get('max_aboard'),greedy_nodes=g.get('nodes_seen'),constructor_status=m.get('constructor_status'),constructor_time_s=m.get('constructor_time_s'),constructor_loaded=c.get('partial_loaded'),constructor_backtracks=c.get('backtracks'),securing_screen_rejections=c.get('securing_screen_rejections'),securing_screen_last_reason=c.get('securing_screen_last_reason'),securing_screen_metrics=c.get('securing_screen'),constructor_restarts=c.get('restarts'),constructor_deficits=c.get('v4_last_deficits'),constructor_reservation_prunes=c.get('v4_reservation_prunes'),constructor_capacity=c.get('v4_visibility_capacity'),constructor_empty_causes=g.get('constructor',{}).get('empty_causes',{}),native_completion_samples=g.get('constructor',{}).get('native_completion_samples',[]),prefix_relaxation_probes=g.get('constructor',{}).get('relaxation_probes',[]),prefix_relaxation_errors=g.get('constructor',{}).get('relaxation_probe_errors',[]),terminal_status=m.get('terminal_status'),terminal_time_s=m.get('terminal_time_s'),replay_legal=r.get('replay_legal'),cargo=r.get('cargo'),summary_path=str(p.relative_to(H))))
 totals={j['map_id']:sum(float(r.get('wall_s',0) or 0) for r in rows if r['map_id']==j['map_id']) for j in reg['jobs']}
 evidence=dict(updated_unix=time.time(),completed=(H/'completion.json').exists() and (not (H/'supplemental-config.json').exists() or (H/'supplement-completion.json').exists()),snapshot_sha256=reg['snapshot_sha256'],cohort_sha256=reg['cohort_sha256'],rows=rows,actual_solver_wall_per_map_s=totals,solver_completions=sum(bool(r['solver_complete']) for r in rows),full_checker_certificates=sum(bool(r['checker_certified']) for r in rows))
 (H/'summary.json').write_text(json.dumps(evidence,indent=2,sort_keys=True)+'\n')
 lines=['# Medium long-search evidence','','Train only. This diagnostic is outcome-selected and cannot estimate a population rescue rate. All plans are provisional until the finisher and full checker accept them. No failed bounded search is an infeasibility certificate.','',f"Runtime snapshot `{reg['snapshot_sha256']}`. Frozen cohort `{reg['cohort_sha256']}`. CPU workers≤4, numerical-library threads1, no source edits, GPU, training, git, validation, test or showcase. The immutable source/resources pin is `runtime/snapshot.json`; finisher supplied a separately hashed qualified-cache supplement.",'','The original preregistration is `preregister.json`. `amendment-aggregate-cap.json` interprets the one-hour limit as aggregate per map and splits remaining allowances across subsequent arms; Subsequent workers divide remaining allowance and arm a local aggregate SIGALRM. The external exact-owned-PID watchdog is best effort: sandbox permissions rejected replacement of its recorded PID, so no external signalling guarantee is claimed. `amendment-cp-reserve.json` reserves600s+10s setup of the121-map hour for capacity CP; search uses the remainder. `amendment-securing.json` adds conservative deck securing and actual-mass ordering to the final widened-constructor arm before it starts. `amendment-contiguous-constructor.json` subsequently gives that final arm90%carrier time and retains four contiguous strategies instead of the initially registered16; widening/backtracks/profiles/screen/ordering/budget form a combined intervention. A conditional `restricted_first_staged` probe prioritizes hard/special cargo before weight class only after all main arms, using remaining allowance with one worker per map across both controllers (500random000 instead routes to the genuine legacy beam probe); see `supplemental-config.json`. All effective patched functions, raw results, telemetry and invocation/PID records are retained.','', '| Map | Loads | Variant | Solve | Actual s | Greedy aboard / nodes | Constructor aboard / backtracks | Terminal |','|---|---:|---|---|---:|---|---|---|']
 for r in rows:
  lines.append(f"| {r['map_id']} | {r['n_loads']} | {r['variant']} | {r['status']} | {r['wall_s']:.1f} | {r['greedy_max_aboard']} / {r['greedy_nodes']} | {r['constructor_loaded']} / {r['constructor_backtracks']} | {r['terminal_status']} |")
 lines+=['','Stage allocation: the unchanged public two-step planner gives carrier pre-stow50% of each total allowance; the final constructor_wide wrapper uses90% as explicitly amended; the terminal owns the remaining whole-call deadline. `summary.json` records actual carrier, primary and constructor times and requested fallback allowance. An862s public allowance therefore supplies431s carrier time. Reservation deficit/capacity telemetry belongs to the last observed pruned prefix, which can differ from the deepest prefix.','','| Variant | Finished evaluations | Solver complete | Greedy s | Constructor s | Terminal s |','|---|---:|---:|---:|---:|---:|']
 for name in [c['name'] for c in configs]:
  part=[r for r in rows if r['variant']==name]
  lines.append(f"| {name} | {len(part)} | {sum(bool(r['solver_complete']) for r in part)} | {sum(float(r.get('greedy_time_s') or 0) for r in part):.1f} | {sum(float(r.get('constructor_time_s') or 0) for r in part):.1f} | {sum(float(r.get('terminal_time_s') or 0) for r in part):.1f} |")
 lines+=['','Selection-note correction: original prose described1700sim210 as427/428; its baseline is426/428. The selected seed is unchanged; see `amendment-selection-note.json`.','','Status: '+('all scheduled runs completed' if evidence['completed'] else 'detached experiment in progress')+'.',f"Solver-complete results: {evidence['solver_completions']}; full-checker certificates produced by this search process: {evidence['full_checker_certificates']}. Finishing is delegated to the separate finisher evidence directory.",'','Per-map actual solver wall seconds: `'+json.dumps(totals,sort_keys=True)+'`.','', '## What has been established','','Width terminology: the existing two-step `beam_width` bounds greedy slot alternatives, `4 × width`;4/16/32mean16/64/128slot alternatives. It is not a retained-breadth beam. The v4fallback is reservation DFS; its actual widening is profile count and backtracking. ScalableConfig beam fields do not widen v4DFS. A separate explicitly labelled `legacy_wide_beam` probe is registered for500random000 after its main arms, replacing its priority extra, with constructor_v4False,retainedwidth16,earlywidth32,branch64,zero neighborhoods,global screenOFF,one contiguous attempt; its actual result is listed only when completed.','','The unchanged configuration receives 3600s but retains the 10s greedy cap and four128-backtrack constructor attempts (512 total). Every observed unchanged arm exhausts that bounded search far before its wall deadline. A larger requested allowance alone does not widen the candidate domain or backtrack count. The constructor explicitly restricts itself to monotone placements without forced ship restows and, before widening, three distinct full-fact cargo profiles per state.','', 'Reservation deficits and remaining-capacity records are branch-specific necessary bounds under that monotone search. They identify a failed prefix, never physical infeasibility of the complete map. Greedy progression and raw moves on prefixes are not certified plan quality.','', '## Reproduction','','Run `.venv/bin/python experiments/mvp/strategy/medium-wall/search/search.py launch` from the repository root to resume missing summaries with the same registered jobs. Do not duplicate an active controller. Owned controller/worker PIDs are in `launch.json`, `controller.json`, `owned-pids.json`, and `watchdog-launch.json`; only those PIDs may be stopped. Run `analyze.py` to refresh this table.']
 lines+=['','## Best physical progress by selected map','','| Map | Loads | Best greedy aboard | Best constructor aboard | Solver complete | Actual search s |','|---|---:|---:|---:|---:|---:|']
 for j in reg['jobs']:
  part=[r for r in rows if r['map_id']==j['map_id']]
  lines.append(f"| {j['map_id']} | {j['n_loads']} | {max([float(r.get('greedy_max_aboard') or 0) for r in part],default=0):.0f} | {max([float(r.get('constructor_loaded') or 0) for r in part],default=0):.0f} | {sum(bool(r['solver_complete']) for r in part)} | {totals[j['map_id']]:.1f} |")
 lines+=['','## Securing-aware combined intervention','','The final widened constructor also adds conservative design-envelope force screening and actual-mass ordering. Its lower completion depth cannot be attributed to width alone. Cached rejection events can greatly exceed distinct force calculations. The conservative envelope can reject arrangements that would pass at their actual loading condition; these are search failures, not physical infeasibility proofs.','','| Map | Aboard | Screen rejection events | Screen placement s | Distinct force evaluations / s | Last reason |','|---|---:|---:|---:|---|---|']
 for r in rows:
  if r['variant']!='constructor_wide':continue
  m=r.get('securing_screen_metrics') or {}
  lines.append(f"| {r['map_id']} | {r['constructor_loaded']} | {r.get('securing_screen_rejections')} | {float(m.get('placement_seconds',0)):.1f} | {m.get('evaluations')} / {float(m.get('evaluation_seconds',0)):.1f} | {r.get('securing_screen_last_reason')} |")
 lines+=['','Verification: `verification.json` records 24 model-validated planner results, unchanged hashes for 517 runtime source/resource files and 1,702 qualified cache files, wrapper setup smokes, JSON/AST checks, inventory/non-overlap audits and actual map budget caps. `completion-reconciled.json` separates two retried interpreter setup failures from planner outcomes. All owned numerical search work is complete.']
 if (H/'FINDINGS.md').exists():lines+=['','## Ranked findings and recommendation','',(H/'FINDINGS.md').read_text().strip()]
 prose='\n'.join(lines)+'\n'
 prose=prose.replace('None / None','—').replace('remaining whole-call deadline. `summary.json`','remaining whole-call deadline. The supplemental priority and genuine-beam probes use 95% carrier time. `summary.json`')
 replacements={'CPU workers≤4, numerical-library threads1':'CPU workers ≤ 4, numerical-library threads = 1','; Subsequent workers':'. Subsequent workers','reserves600s+10s setup of the121-map hour':'reserves 600 s plus 10 s setup from each 121-container map allowance','arm90%carrier time':'arm 90% carrier time','initially registered16':'initially registered 16','pre-stow50%':'pre-stow 50%','uses90%':'uses 90%','An862s public allowance therefore supplies431s carrier time':'An 862 s public allowance therefore supplies 431 s carrier time','described1700sim210 as427/428; its baseline is426/428':'described 1700sim210 as 427/428; its baseline is 426/428',';4/16/32mean16/64/128slot alternatives':'; 4/16/32 mean 16/64/128 slot alternatives','v4fallback':'v4 fallback','v4DFS':'v4 DFS','registered for500random000':'registered for 500random000','constructor_v4False,retainedwidth16,earlywidth32,branch64,zero neighborhoods,global screenOFF,one contiguous attempt':'constructor_v4=False, retained width 16, early width 32, branch factor 64, zero neighborhoods, global screen OFF, and one contiguous attempt','four128-backtrack':'four 128-backtrack','3600s':'3600 s','10s':'10 s'}
 for old,new in replacements.items():prose=prose.replace(old,new)
 (H/'SEARCH.md').write_text(prose)
 print(json.dumps(dict(completed=len(rows),solver_completions=evidence['solver_completions'],wall_s=totals)))
if __name__=='__main__':main()
